function separate_paren_groups(paren_string){
    const groups = [];
    let currentGroup = '';
    let depth = 0;

    for (const char of paren_string.replace(/\s+/g, '')) {
        if (char === '(') {
            depth++;
            currentGroup += char;
        } else if (char === ')') {
            depth--;
            currentGroup += char;
            if (depth === 0) {
                groups.push(currentGroup);
                currentGroup = '';
            }
        }
    }

    return groups;
}

